#include "Plugin.cpp"
#include <iostream>
int main(){juce::ScopedJuceInitialiser_GUI init;Processor p;{std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());auto image=editor->createComponentSnapshot(editor->getLocalBounds(),true,2.f);juce::FileOutputStream stream(juce::File::getCurrentWorkingDirectory().getChildFile("outputs/GUI-preview.png"));juce::PNGImageFormat png;png.writeImageToStream(image,stream);}auto set=[&](const char* id,float v){auto* a=p.state.getParameter(id);a->setValueNotifyingHost(a->convertTo0to1(v));};auto run=[&](){p.prepareToPlay(48000,256);juce::AudioBuffer<float>b(2,256);juce::MidiBuffer m;double sum=0;for(int k=0;k<600;k++){for(int i=0;i<256;i++)for(int c=0;c<2;c++)b.setSample(c,i,0.25f*std::sin(2*juce::MathConstants<double>::pi*440*(k*256+i)/48000));p.processBlock(b,m);if(k>500)for(int i=0;i<256;i++)sum+=b.getSample(0,i)*b.getSample(0,i);}return std::sqrt(sum/(99*256));};set("gain",60);set("squeeze",0);double dry=run();set("squeeze",35);double gentle=run();set("squeeze",70);double compressed=run();set("squeeze",100);double strong=run();set("squeeze",70);set("mode",1);double limited=run();set("mix",0);double mixed=run();set("bypass",1);double bypass=run();juce::MemoryBlock state;p.getStateInformation(state);set("squeeze",22);p.setStateInformation(state.getData(),(int)state.getSize());bool ok=std::abs(dry-0.17677)<0.001&&gentle<=dry&&strong<compressed&&compressed<gentle&&compressed<dry&&limited<compressed&&std::abs(mixed-dry)<0.001&&std::abs(bypass-dry)<0.001&&p.v("squeeze")==70;std::cout<<"dry="<<dry<<" gentle="<<gentle<<" strong="<<strong<<" compressed="<<compressed<<" limit="<<limited<<" mix0="<<mixed<<" bypass="<<bypass<<" state="<<p.v("squeeze")<<" PASS="<<ok<<std::endl;return ok?0:1;}


